-- 300,000 orders from 5,000 customers: the order history imported from the old shop.
insert into public.orders (customer_email, status, total_cents, created_at)
select
  'customer-' || (n % 5000) || '@example.com',
  (array['pending', 'paid', 'shipped', 'refunded'])[1 + n % 4],
  500 + (n * 37) % 49500,
  timestamptz '2024-01-01 00:00:00+00' + n * interval '3 minutes'
from generate_series(1, 300000) as n;

analyze public.orders;

